        let (mut a, _) = seated(&state, &log, "alice").await;
        assert!(stored(&put(&mut a, &log, Frame::start(1)).await));
        let id = count(&state, "SELECT id FROM voipc_chains").await;
        run(&state, "DELETE FROM voipc_chains").await;
